#!/usr/bin/env node
/**
 * 800-line source-file guard. Fails when any hand-written file
 * under `src/` exceeds 800 lines. `src/worker-configuration.d.ts` is
 * generated by `wrangler types` and is exempt.
 *
 * Credential-free: walks the working tree and counts lines, no network.
 * Pure logic lives in `./lib/sourceFileSize.mjs` and is unit-tested; this
 * wrapper is intentionally thin.
 *
 * Usage:
 *   npm run check:source-file-size [-- --limit=N]
 */
import { readdirSync, readFileSync, statSync } from "node:fs";
import path from "node:path";
import { argv, exit } from "node:process";

import {
  CHECK_NAME,
  DEFAULT_LIMIT,
  findOversize,
  formatFailureLog,
  formatPassLog,
} from "./lib/sourceFileSize.mjs";

const root = path.join(path.dirname(new URL(import.meta.url).pathname), "..");

function usage() {
  return [
    "Usage: node scripts/check-source-file-size.mjs [--limit=N]",
    "",
    `  --limit=N  Maximum lines per hand-written src/ file (default ${DEFAULT_LIMIT}).`,
  ].join("\n");
}

let limit = DEFAULT_LIMIT;
for (const arg of argv.slice(2)) {
  if (arg === "--help" || arg === "-h") {
    console.log(usage());
    exit(0);
  } else if (arg.startsWith("--limit=")) {
    const n = Number(arg.slice("--limit=".length));
    if (!Number.isInteger(n) || n <= 0) {
      console.error(`${CHECK_NAME}: --limit must be a positive integer (got ${arg.slice("--limit=".length)})`);
      exit(1);
    }
    limit = n;
  } else {
    console.error(`Unknown flag: ${arg}\n\n${usage()}`);
    exit(1);
  }
}

function walk(dir, out) {
  for (const entry of readdirSync(dir)) {
    const full = path.join(dir, entry);
    if (statSync(full).isDirectory()) {
      walk(full, out);
    } else {
      out.push(full);
    }
  }
  return out;
}

let files;
try {
  files = walk(path.join(root, "src"), []);
} catch (error) {
  console.error(`${CHECK_NAME}: FAIL — cannot read src/: ${error.message}`);
  exit(1);
}

const entries = files.map((full) => ({
  path: path.relative(root, full).replaceAll("\\", "/"),
  text: readFileSync(full, "utf8"),
}));

const offenders = findOversize(entries, { limit });
if (offenders.length > 0) {
  console.error(formatFailureLog(offenders, limit));
  exit(1);
}
console.log(formatPassLog(entries.length, limit));
